// Protection throughput index — record JAH-GPC-FIREWALLAPPLIANCE-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"throughput_mbps": 1000, "ports": 4, "price_usd": 300};
var value = (m.throughput_mbps*m.ports/m.price_usd);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPC-FIREWALLAPPLIANCE-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPC-FIREWALLAPPLIANCE-000001|' + value.toFixed(2) + ' protection index');

